 show('#partialCount',full||experiment==='harmonics');$('partialCount').closest('label').hidden=!(full||experiment==='harmonics');
 show('#advanced',full||['beats','phase','missing'].includes(experiment));
 show('#timeWindow',full||experiment==='beats');$('timeWindow').closest('label').hidden=!(full||experiment==='beats');
 show('#freqScale, .analyser-options, #resolutionNote',full);
 show('#individuals',full);$('individuals').closest('label').hidden=!full;
 show('#captureBtn',full||experiment==='vowels');
 show('#clearCaptureBtn',!!comparison&&(full||experiment==='vowels'));
 show('#spectrogramToggle',full||experiment==='vowels');$('spectrogramToggle').closest('label').hidden=!(full||experiment==='vowels');
