$('audioFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024){notice('fileLarge',{},true);return;}const gen=++fileGeneration;stopFile(false);playing=false;fileBuffer=null;fileOffset=0;$('seek').disabled=true;updateButtons();notice('loading');try{await ensureAudio();const buffer=await ctx.decodeAudioData(await file.arrayBuffer());if(gen!==fileGeneration)return;fileBuffer=buffer;$('fileName').textContent=file.name;$('seek').max=buffer.duration;$('seek').disabled=false;notice('fileReady');updateButtons();dirty=true;}catch{if(gen===fileGeneration)notice('fileError',{},true);}};
