function loadShare(){if(!location.hash.startsWith('#sound='))return;try{const encoded=location.hash.slice(7);if(encoded.length>20000)throw new Error('Too large');const raw=atob(encoded.replaceAll('-','+').replaceAll('_','/')),payload=JSON.parse(new TextDecoder().decode(Uint8Array.from(raw,c=>c.charCodeAt(0))));if(payload.v!==1)throw new Error('Version');const valid=validateSound(payload.sound);if(payload.lang==='de'||payload.lang==='en')lang=payload.lang;if(payload.experiment&&experiments[payload.experiment])startExperiment(payload.experiment);else{experiment=null;stage='explore';chooseSource('synth');}setSound(valid);applyLanguage();notice('loadedShare');}catch{notice('invalidShare',{},true);}}
