if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_sound_lab',description:'Read current synthesizer settings, source and experiment.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({sound:snapshot(),source,experiment,playing})},{name:'configure_sound_lab',description:'Set the synthesizer frequency and waveform without starting playback.',inputSchema:{type:'object',properties:{frequency:{type:'number',minimum:20,maximum:20000},waveform:{type:'string',enum:['sine','triangle','saw','square']}},required:['frequency','waveform'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.frequency!=='number'||!Number.isFinite(input.frequency)||input.frequency<20||input.frequency>20000||!['sine','triangle','saw','square'].includes(input.waveform))throw new Error('Invalid frequency or waveform');chooseSource('synth');setSound({fundamental:input.frequency,harmonic:true,preset:input.waveform,partials:makePartials(sound.partials.length,input.waveform,input.frequency)});return{sound:snapshot(),playing:false};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
